// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"nabiximols":{"wirkmechanismus":"Lindert die Muskelsteifigkeit und Krämpfe bei Multipler Sklerose über das körpereigene Cannabinoid-System. Delta-9-Tetrahydrocannabinol (THC) wirkt als partieller Agonist an Cannabinoid-Rezeptoren (CB1 und CB2); CB1-Rezeptoren an Nervenendigungen hemmen die Freisetzung von Botenstoffen und vermindern so die übermässige Muskelspannung. Cannabidiol (CBD) beeinflusst die Wirkung von THC und mildert möglicherweise einen Teil der psychischen Effekte. Beide werden über die Mundschleimhaut aufgenommen und in der Leber vor allem über CYP3A4, CYP2C9 und CYP2C19 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Müdigkeit"],"haeufig":["Depression, Orientierungsstörung, Euphorie","Gedächtnis-, Konzentrations- und Gleichgewichtsstörungen, Schläfrigkeit","Verschwommenes Sehen, Drehschwindel","Übelkeit, Erbrechen, Durchfall oder Verstopfung, Mundtrockenheit","Schmerzen, Brennen oder Geschwüre im Mund","Appetitveränderungen","Stürze, Trunkenheitsgefühl"],"gelegentlich":["Halluzinationen, Wahnvorstellungen, Paranoia","Suizidgedanken","Ohnmacht (Synkope)","Herzklopfen, Herzrasen, Bluthochdruck","Verfärbung von Mundschleimhaut oder Zähnen, Schleimhautablösungen"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar das Risiko. Frauen und ihre Partner sollen während der Behandlung und bis 3 Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert, da Cannabinoide in grösseren Mengen in die Muttermilch übergehen.","hinweise":["Nicht Auto fahren, solange die Wirkung nicht bekannt ist; Schwindel und Schläfrigkeit sind häufig. Kein Alkohol.","Der Nutzen wird nach etwa 4 Wochen ärztlich überprüft; ohne deutliche Besserung wird die Behandlung beendet.","Sprühstelle in der Mundhöhle regelmässig wechseln und die Mundschleimhaut kontrollieren.","Untersteht dem Betäubungsmittelgesetz; bei Auslandreisen eine ärztliche Bescheinigung mitführen."],"darreichung":["Spray zur Anwendung in der Mundhöhle"]},"nadroparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Nadroparin ist ein niedermolekulares Heparin, das den körpereigenen Hemmstoff Antithrombin aktiviert; dadurch wird vor allem der Gerinnungsfaktor Xa, in geringerem Mass Thrombin (Faktor IIa), gehemmt. Die Wirkung ist besser vorhersehbar und länger als bei unfraktioniertem Heparin, sodass es ein- bis zweimal täglich unter die Haut gespritzt wird. Die Ausscheidung erfolgt überwiegend über die Nieren.","nebenwirkungen":{"sehrHaeufig":["Blutungen an verschiedenen Stellen (häufiger bei zusätzlichen Risikofaktoren)","Kleiner Bluterguss an der Einstichstelle"],"haeufig":["Reaktionen an der Einstichstelle","Vorübergehender Anstieg der Leberwerte (Transaminasen)"],"selten":["Thrombozytopenie (verminderte Blutplättchen), auch heparininduzierte Thrombozytopenie Typ II mit Thrombosen","Hautausschlag, Nesselsucht, Juckreiz","Kalkablagerungen oder Knötchen an der Einstichstelle"],"sehrSelten":["Überempfindlichkeitsreaktionen bis anaphylaktoide Reaktion, Angioödem","Hyperkaliämie (erhöhtes Kalium)","Hautnekrosen an der Einstichstelle","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Priapismus (schmerzhafte Dauererektion)"],"unbekannt":["Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie mit möglicher Lähmung"]},"schwangerschaft":"Nur begrenzte Erfahrungen; Anwendung nur nach strenger ärztlicher Abwägung. Für andere niedermolekulare Heparine liegen mehr Daten vor; eine rückenmarksnahe Anästhesie bei der Geburt muss zeitlich abgestimmt werden.","stillzeit":"Nur wenige Daten; eine Aufnahme über den Darm des Säuglings ist unwahrscheinlich. Anwendung nach ärztlicher Abwägung.","hinweise":["Unter die Haut spritzen (Bauch), nie in den Muskel; Einstichstelle wechseln und nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen"]},"naftidrofuryl":{"wirkmechanismus":"Verbessert Durchblutung und Stoffwechsel in schlecht durchbluteten Geweben. Naftidrofuryl blockiert Serotonin-5-HT2-Rezeptoren an der Gefässmuskulatur und an den Blutplättchen und wirkt so einer serotoninbedingten Gefässverengung und Plättchenzusammenlagerung entgegen. Zudem verbessert es die Sauerstoff- und Energieverwertung der Zellen.","nebenwirkungen":{"haeufig":["Übelkeit","Bauchschmerzen","Durchfall"],"sehrSelten":["Leberentzündung (Hepatitis) bis Leberversagen","Calciumoxalat-Nierensteine"],"unbekannt":["Hautausschlag und andere allergische Hautreaktionen","Speiseröhrenentzündung (Ösophagitis) bei Einnahme ohne ausreichend Flüssigkeit"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; aus Vorsicht nicht anwenden.","stillzeit":"Nicht bekannt, ob Naftidrofuryl in die Muttermilch übergeht; in der Stillzeit nicht empfohlen.","hinweise":["Tabletten unzerkaut während der Mahlzeiten mit einem grossen Glas Wasser einnehmen und sich danach nicht gleich hinlegen.","Über den Tag ausreichend trinken, um Nierensteinen vorzubeugen.","Gehtraining und Rauchstopp bleiben die wichtigsten Massnahmen bei Schaufensterkrankheit."],"darreichung":["Filmtabletten"]},"naftifin":{"wirkmechanismus":"Tötet Hautpilze ab, indem es ein Enzym für den Aufbau ihrer Zellmembran blockiert. Naftifin hemmt die Squalen-Epoxidase der Pilze; dadurch fehlt Ergosterol in der Membran, und gleichzeitig reichert sich für den Pilz giftiges Squalen an. Gegen Fadenpilze wirkt es abtötend (fungizid), gegen Hefen vor allem wachstumshemmend. Zusätzlich hat Naftifin eine leichte entzündungshemmende Wirkung.","nebenwirkungen":{"gelegentlich":["Lokale Hautreaktionen wie Trockenheit, Rötung oder Brennen"],"unbekannt":["Allergische Kontaktdermatitis, Juckreiz"]},"schwangerschaft":"Nur geringe Aufnahme ins Blut, aber wenig Erfahrung; nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nur nach ärztlicher Abwägung; nicht im Brustbereich auftragen, damit das Kind nicht mit dem Wirkstoff in Kontakt kommt.","hinweise":["Behandlung nach Abklingen der Beschwerden noch mindestens 2 Wochen fortsetzen.","Haut vor dem Auftragen reinigen und gut trocknen; Handtücher und Socken häufig wechseln.","Ohne Besserung nach 4 Wochen ärztlich abklären.","Nicht in die Augen oder auf Schleimhäute bringen."],"darreichung":["Creme","Lösung"]},"nalbuphin":{"wirkmechanismus":"Lindert Schmerzen über Opioidrezeptoren im Nervensystem, dämpft die Atmung aber weniger stark als reine Opioide. Nalbuphin aktiviert κ-Opioidrezeptoren und blockiert gleichzeitig µ-Opioidrezeptoren teilweise (gemischter Agonist-Antagonist). Ab einer bestimmten Dosis nimmt die Atemdämpfung kaum mehr zu (Ceiling-Effekt), allerdings auch die Schmerzlinderung nicht. Bei Personen, die an reine Opioide gewöhnt sind, kann es Entzugssymptome auslösen; die Wirkung lässt sich mit Naloxon aufheben.","nebenwirkungen":{"sehrHaeufig":["Sedierung (Schläfrigkeit)"],"haeufig":["Schwitzen, feuchtkalte Haut","Übelkeit, Erbrechen","Schwindel","Mundtrockenheit","Kopfschmerzen"],"unbekannt":["Atemdepression (abgeflachte Atmung)","Verwirrtheit, Unruhe, Halluzinationen, Verstimmung","Blutdruckabfall oder -anstieg, Herzrasen oder langsamer Puls","Allergische Reaktionen bis Anaphylaxie","Entzugssymptome bei Gewöhnung an Opioide","Abhängigkeit bei längerer Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Gabe unter der Geburt können beim Kind ein verlangsamter Herzschlag und nach der Geburt eine Atemdepression auftreten – Überwachung nötig.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nach einzelnen Gaben Stillen nur nach ärztlicher Abwägung, Säugling auf Schläfrigkeit beobachten.","hinweise":["Kein Alkohol und keine anderen Beruhigungsmittel ohne ärztliche Rücksprache.","Nach der Anwendung nicht Auto fahren und keine Maschinen bedienen.","Wer regelmässig Opioide einnimmt, muss dies angeben: Nalbuphin kann Entzugserscheinungen auslösen."],"darreichung":["Injektionslösung"]},"naloxegol":{"wirkmechanismus":"Hebt die verstopfende Wirkung von Opioid-Schmerzmitteln im Darm auf, ohne die Schmerzlinderung aufzuheben. Naloxegol ist ein mit Polyethylenglykol verknüpftes (PEGyliertes) Naloxon-Derivat, das die µ-Opioidrezeptoren im Magen-Darm-Trakt blockiert. Da es vom Transporter P-Glykoprotein aus dem Gehirn hinausbefördert wird, gelangt es kaum ins zentrale Nervensystem.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Durchfall"],"haeufig":["Blähungen","Übelkeit","Erbrechen","Kopfschmerzen","Vermehrtes Schwitzen (Hyperhidrose)","Nasen-Rachen-Entzündung"],"gelegentlich":["Opioid-Entzugssyndrom (z. B. Frösteln, Schwitzen, Unruhe, Gähnen)"],"unbekannt":["Überempfindlichkeitsreaktionen","Magen-Darm-Perforation (Durchbruch der Darmwand)"]},"schwangerschaft":"Nicht empfohlen (begrenzte Erfahrungen; beim Ungeborenen sind Entzugssymptome möglich).","stillzeit":"Während der Stillzeit nicht anwenden.","hinweise":["Morgens nüchtern einnehmen, mindestens 30 Minuten vor der ersten Mahlzeit des Tages.","Während der Behandlung keinen Grapefruitsaft trinken.","Bisherige regelmässige Abführmittel werden zu Behandlungsbeginn abgesetzt; bei Bedarf sind Reserve-Abführmittel erlaubt.","Starke, anhaltende oder zunehmende Bauchschmerzen sofort ärztlich melden."],"darreichung":["Filmtabletten"]},"naloxon":{"wirkmechanismus":"Verdrängt Opioide von ihren Bindungsstellen im Gehirn und hebt so ihre Wirkung, vor allem die lebensgefährliche Atemdämpfung, innert Minuten auf. Naloxon ist ein reiner kompetitiver Antagonist an den µ-, κ- und δ-Opioidrezeptoren ohne eigene opioidartige Wirkung. Seine Wirkung hält nur etwa 1–2 Stunden an und ist damit kürzer als die vieler Opioide – die Atemdämpfung kann zurückkehren. Gegen Vergiftungen mit Benzodiazepinen, Alkohol oder anderen Nicht-Opioiden wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Schwindel, Kopfschmerzen","Tachykardie (Herzrasen)","Blutdruckabfall oder -anstieg","Erbrechen","Schmerzen nach Operationen"],"gelegentlich":["Zittern, Schwitzen","Herzrhythmusstörungen, Bradykardie (verlangsamter Puls)","Durchfall, Mundtrockenheit","Hyperventilation (beschleunigte Atmung)","Reizung an der Injektionsstelle"],"selten":["Krampfanfälle"],"sehrSelten":["Allergische Reaktionen bis zum anaphylaktischen Schock","Kammerflimmern, Herzstillstand","Lungenödem (Wasser in der Lunge)","Erythema multiforme (schwere Hautreaktion)"],"unbekannt":["Akutes Opioid-Entzugssyndrom bei Abhängigen (Unruhe, Gänsehaut, Gähnen, Bauchkrämpfe)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden – im Notfall aber ohne Zögern. Bei opioidabhängigen Schwangeren kann auch beim Ungeborenen ein Entzug ausgelöst werden.","stillzeit":"Ob Naloxon in die Muttermilch übergeht, ist nicht bekannt; es wird über den Darm kaum aufgenommen. Gestillte Säuglinge 24 Stunden lang beobachten.","hinweise":["Nach jeder Anwendung sofort den Notruf 144 alarmieren und die Person bis zum Eintreffen des Rettungsdienstes nicht allein lassen – die Wirkung hält kürzer an als die vieler Opioide.","Nasenspray: Person auf den Rücken legen, einen Sprühstoss in ein Nasenloch geben; ohne Besserung nach 2–3 Minuten die zweite Dosis ins andere Nasenloch, danach Seitenlage.","Erneuter Opioidkonsum gegen die Entzugsbeschwerden ist gefährlich: nach dem Abklingen von Naloxon droht erneut eine Überdosis."],"darreichung":["Injektionslösung","Nasenspray (Einzeldosis)"]},"nandrolon":{"wirkmechanismus":"Fördert den Aufbau von Muskel- und Knochengewebe sowie die Blutbildung. Nandrolon ist ein Abkömmling des männlichen Hormons Testosteron (19-Nortestosteron) und bindet an den Androgenrezeptor; im Verhältnis zu Testosteron überwiegt die eiweissaufbauende (anabole) gegenüber der vermännlichenden (androgenen) Wirkung. Es steigert die Bildung von Erythropoetin und regt die Blutbildung im Knochenmark an. Als Decanoat-Ester in Öl wird es nach der Injektion über Wochen langsam freigesetzt.","nebenwirkungen":{"unbekannt":["Vermännlichung bei Frauen: Heiserkeit, tiefere Stimme, Akne, vermehrte Körperbehaarung, Vergrösserung der Klitoris","Zyklusstörungen, Ausbleiben der Regelblutung","Ödeme (Wassereinlagerungen)","Veränderte Blutfette (HDL-Cholesterin sinkt)","Leberfunktionsstörungen; bei hoher Dosierung und Langzeitanwendung Blutzysten in der Leber (Peliosis hepatis) und Lebertumoren","Priapismus (schmerzhafte Dauererektion), Hemmung der Spermienbildung","Hyperkalzämie (erhöhtes Calcium)","Reaktionen an der Injektionsstelle"]},"schwangerschaft":"Kontraindiziert: kann beim weiblichen Kind eine Vermännlichung verursachen.","stillzeit":"Nicht anwenden.","hinweise":["Steht auf der Dopingliste; die Anwendung ist im Wettkampfsport verboten.","Regelmässige Kontrollen von Blutbild, Leberwerten, Blutfetten und bei Männern der Prostata.","Frauen: erste Zeichen einer Vermännlichung (z. B. Heiserkeit) sofort melden, da sie bleibend sein können."],"darreichung":["Ölige Injektionslösung (intramuskulär)"]},"naproxen":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Naproxen hemmt reversibel die Cyclooxygenasen COX-1 und COX-2. Dank der langen Halbwertszeit von 12–17 Stunden genügen meist ein bis zwei Einnahmen pro Tag; die Natrium-Salzform wird schneller aufgenommen und wirkt rascher.","nebenwirkungen":{"haeufig":["Sodbrennen, Dyspepsie (Verdauungsbeschwerden), Übelkeit, Bauchschmerzen","Verstopfung, Durchfall","Kopfschmerzen, Schwindel, Benommenheit","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen)","Ohrensausen (Tinnitus)"],"unbekannt":["Magen-Darm-Geschwüre, -Blutungen und -Durchbrüche","Anaphylaxie (schwere allergische Reaktion) und Asthmaanfälle","Blutbildstörungen bis Agranulozytose (Ausfall der weissen Blutkörperchen)","Hepatitis, Leberschäden","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse); Lichtempfindlichkeit mit Blasenbildung","Nierenschäden bis akutes Nierenversagen","Herzinfarkt, Schlaganfall, Herzinsuffizienz","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich (ab der 20. Woche Risiko für Nierenschäden beim Kind und Fruchtwassermangel). Im letzten Drittel kontraindiziert.","stillzeit":"Geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Mit einem Glas Wasser, bei Magenbeschwerden zu einer Mahlzeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","So niedrig dosiert und so kurz wie möglich anwenden; rezeptfreie Präparate ohne ärztlichen Rat nur wenige Tage einnehmen.","Kann Schwindel und Benommenheit verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten","Filmtabletten"]},"naratriptan":{"wirkmechanismus":"Lindert Migränekopfschmerzen, indem es erweiterte Blutgefässe im Kopf verengt und die Schmerzentzündung an den Nerven dämpft. Naratriptan aktiviert Serotonin-Rezeptoren vom Typ 5-HT1B an Hirngefässen und 5-HT1D an Endigungen des Trigeminusnervs und hemmt so die Freisetzung entzündungsfördernder Botenstoffe wie CGRP. Mit einer Halbwertszeit von etwa 6 Stunden wirkt es länger als Sumatriptan, was Kopfschmerzrückfälle seltener machen kann. Es wird zu einem grossen Teil unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Kribbeln (Parästhesien)","Schwindel, Schläfrigkeit","Übelkeit, Erbrechen","Hitzegefühl","Unwohlsein, Müdigkeit"],"gelegentlich":["Sehstörungen","Herzklopfen, langsamer oder schneller Puls","Druck-, Enge- oder Schweregefühl in Brust, Hals oder anderen Körperteilen"],"selten":["Allergische Reaktionen bis Anaphylaxie, Hautausschlag, Angioödem (Schwellungen)"],"sehrSelten":["Verkrampfung der Herzkranzgefässe, Angina pectoris, Herzinfarkt","Durchblutungsstörungen in Beinen oder Darm (ischämische Kolitis)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; die Erfahrungen sind begrenzt.","stillzeit":"Bis 24 Stunden nach der Einnahme nicht stillen; in dieser Zeit abgepumpte Milch verwerfen.","hinweise":["Erst einnehmen, wenn die Kopfschmerzen beginnen – nicht vorbeugend und nicht während der Aura.","Höchstens 5 mg (2 Tabletten) in 24 Stunden; eine zweite Tablette frühestens nach 4 Stunden und nur, wenn die Kopfschmerzen nach anfänglicher Besserung zurückkehren.","An mehr als 10 Tagen pro Monat eingenommen, können Triptane selbst Kopfschmerzen verursachen.","Bei Brustschmerzen oder Engegefühl in Brust oder Hals ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"natalizumab":{"wirkmechanismus":"Verhindert, dass weisse Blutkörperchen aus dem Blut ins Gehirn und Rückenmark einwandern und dort Entzündungsherde bilden. Natalizumab ist ein humanisierter monoklonaler Antikörper gegen die Alpha-4-Untereinheit der Integrine α4β1 (VLA-4) und α4β7. Er blockiert deren Bindung an VCAM-1 auf den Zellen der Gefässwand und damit den Durchtritt aktivierter Lymphozyten durch die Blut-Hirn-Schranke. Die Kehrseite ist eine verminderte Immunüberwachung des Zentralnervensystems mit dem Risiko einer progressiven multifokalen Leukoenzephalopathie (PML).","nebenwirkungen":{"haeufig":["Harnwegsinfekte, Nasen-Rachen-Entzündung","Kopfschmerzen, Schwindel","Übelkeit, Erbrechen","Gelenkschmerzen","Müdigkeit, Fieber, Schüttelfrost","Überempfindlichkeits- und Infusionsreaktionen (z. B. Nesselsucht, Juckreiz, Ausschlag)"],"gelegentlich":["Progressive multifokale Leukoenzephalopathie (PML, schwere Hirninfektion durch das JC-Virus)","Anaphylaxie (schwere allergische Reaktion)","Thrombozytopenie (Mangel an Blutplättchen), Immunthrombozytopenie","Immunrekonstitutionssyndrom (IRIS) nach Absetzen bei PML"],"selten":["Hämolytische Anämie (Blutarmut durch Blutzerfall)"],"unbekannt":["Herpes-Hirn- oder Hirnhautentzündung, akute Netzhautnekrose","Leberschädigung"]},"schwangerschaft":"Nur anwenden, wenn eindeutig erforderlich; bei Eintritt einer Schwangerschaft entscheidet die Ärztin oder der Arzt über die Fortsetzung. Nach Anwendung im letzten Drittel können beim Neugeborenen Blutplättchenmangel und Blutarmut auftreten.","stillzeit":"Natalizumab geht in die Muttermilch über; ob gestillt oder die Behandlung fortgesetzt wird, ist ärztlich abzuwägen.","hinweise":["Patientenkarte mitführen. Neue oder zunehmende neurologische Beschwerden (Lähmungen, Sehstörungen, Sprach-, Gedächtnis- oder Verhaltensänderungen) sofort melden – auch bis 6 Monate nach Therapieende (PML).","Infusion nur in einer spezialisierten Einrichtung; danach Überwachung wegen möglicher Überempfindlichkeitsreaktionen.","Regelmässige Kontrollen: JC-Virus-Antikörper, MRI, Blutbild und Leberwerte."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"nateglinid":{"wirkmechanismus":"Regt die Bauchspeicheldrüse sehr rasch und nur kurz zur Insulinausschüttung an. Nateglinid, ein Abkömmling der Aminosäure Phenylalanin, schliesst die ATP-abhängigen Kaliumkanäle der Betazellen. Die Insulinfreisetzung beginnt innerhalb von etwa 15 Minuten, ist von der Blutzuckerhöhe abhängig und dauert nur wenige Stunden. Abgebaut wird Nateglinid überwiegend über CYP2C9, zu einem kleineren Teil über CYP3A4.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung)","Bauchschmerzen","Durchfall, Übelkeit, Verdauungsbeschwerden"],"gelegentlich":["Erbrechen"],"selten":["Erhöhte Leberwerte","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht)"]},"schwangerschaft":"Kontraindiziert; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Kontraindiziert.","hinweise":["Kurz (bis 30 Minuten) vor den Hauptmahlzeiten einnehmen; wird eine Mahlzeit ausgelassen, auch die Tablette auslassen.","Zeichen einer Unterzuckerung kennen und Traubenzucker mitführen; Alkohol erhöht das Risiko.","Unterzuckerungen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"natriumalginat":{"wirkmechanismus":"Legt sich wie ein schützender Deckel auf den Mageninhalt und hält so Magensäure von der Speiseröhre fern. Im sauren Magen bildet Natriumalginat zusammen mit dem in den Präparaten enthaltenen Hydrogencarbonat (und teils Calcium) ein zähes Gel; das entstehende Kohlendioxid lässt diese Gelschicht («Raft») auf dem Mageninhalt schwimmen. Bei Reflux steigt vor allem das weitgehend säureneutrale Gel in die Speiseröhre auf. Säurebindende Zusätze wie Natrium- oder Kaliumhydrogencarbonat und Calciumcarbonat neutralisieren zusätzlich Magensäure; das Alginat selbst wird nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrSelten":["Anaphylaktische oder anaphylaktoide Reaktionen","Überempfindlichkeitsreaktionen wie Nesselsucht","Atemwegsreaktionen wie Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Hyperkalzämie, Alkalose oder Milch-Alkali-Syndrom bei hoher, längerer Einnahme calciumhaltiger Präparate","Blähungen und Völlegefühl bei Einnahme grosser Mengen"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden; umfangreiche Erfahrungen zeigen keine schädlichen Wirkungen. Natrium- und Calciumgehalt beachten.","stillzeit":"Kann in der Stillzeit angewendet werden.","hinweise":["Nach den Mahlzeiten und vor dem Schlafengehen einnehmen; Suspension vor Gebrauch schütteln, Kautabletten gründlich kauen.","Zu anderen Arzneimitteln etwa 2 Stunden Abstand halten.","Bei kochsalzarmer Diät den Natriumgehalt mit Ärztin, Arzt oder Apotheke besprechen."],"darreichung":["Suspension zum Einnehmen (Flasche oder Beutel)","Kautabletten"]},"natriumchlorid":{"wirkmechanismus":"Ersetzt Wasser und Salz im Raum ausserhalb der Zellen. Natrium und Chlorid sind die wichtigsten Elektrolyte der Körperflüssigkeit ausserhalb der Zellen und bestimmen deren Volumen. Die 0,9 %-Lösung hat etwa die gleiche Teilchenkonzentration wie Blut (isotonisch) und verteilt sich im ganzen Extrazellulärraum, sodass nur etwa ein Viertel in den Blutgefässen bleibt. Weil sie mehr Chlorid enthält als das Blutplasma, kann sie in grossen Mengen eine Übersäuerung (hyperchlorämische Azidose) verursachen. Konzentrierte Lösungen heben den Natriumspiegel gezielt an.","nebenwirkungen":{"unbekannt":["Hypernatriämie (zu hohes Natrium) mit Durst, Unruhe, Verwirrtheit","Hyperchlorämische metabolische Azidose (Übersäuerung) bei grossen Mengen","Überwässerung, Ödeme, Lungenödem, Blutdruckanstieg","Osmotisches Demyelinisierungssyndrom bei zu raschem Ausgleich eines Natriummangels","Reaktionen an der Infusionsstelle (Venenreizung, Venenentzündung, Paravasat)","Fieber, Infektion an der Einstichstelle"]},"schwangerschaft":"Kann angewendet werden; Vorsicht bei Präeklampsie.","stillzeit":"Kann angewendet werden.","hinweise":["Konzentrate (z. B. 11,7 %) nie unverdünnt infundieren – nur als Zusatz zu Infusionslösungen.","Bei Infusionen Elektrolyte, Säure-Basen-Haushalt und Flüssigkeitsbilanz kontrollieren lassen.","Einen chronischen Natriummangel nur langsam ausgleichen (Anstieg des Natriums höchstens etwa 8–10 mmol/l in 24 Stunden)."],"darreichung":["Infusionslösung 0,9 % (isotonisch)","Konzentrat zur Herstellung einer Infusionslösung (z. B. 11,7 %)","Lösung zum Spülen und Verdünnen"]},"natriumcitrat-natriumlaurylsulfoacetat-sorbitol":{"wirkmechanismus":"Weicht den Stuhl im Enddarm auf und erleichtert so eine rasche Entleerung. Die fixe Kombination wirkt rein örtlich: Natriumcitrat verdrängt gebundenes Wasser aus dem Stuhl (peptisierende Wirkung), das Netzmittel Natriumlaurylsulfoacetat lässt Wasser in den harten Stuhl eindringen, und Sorbitol zieht osmotisch Wasser in den Enddarm. Der aufgeweichte Stuhl löst den Entleerungsreflex aus, meist innerhalb von 5 bis 20 Minuten. Die Bestandteile werden kaum in den Körper aufgenommen.","nebenwirkungen":{"unbekannt":["Brennen oder Missempfindungen am After","Bauchschmerzen, Bauchkrämpfe","Weicher Stuhl, Durchfall","Überempfindlichkeitsreaktionen (z. B. Nesselsucht)"]},"schwangerschaft":"Die Bestandteile werden kaum aufgenommen; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Kanüle vollständig einführen (bei Kindern unter 3 Jahren nur zur Hälfte), Tube ganz ausdrücken und erst nach dem Herausziehen loslassen.","Abführmittel nur kurzfristig verwenden; bei anhaltender Verstopfung ärztlich abklären lassen."],"darreichung":["Rektallösung (Mikroklistier)"]},"natriumfluorid":{"wirkmechanismus":"Härtet den Zahnschmelz und macht ihn widerstandsfähiger gegen die Säuren, die Kariesbakterien bilden. Fluorid lagert sich an der Zahnoberfläche als calciumfluoridartige Schicht ab, aus der bei einem Säureangriff Fluorid frei wird; dies bremst die Entkalkung (Demineralisation) und fördert die Wiedereinlagerung von Mineralien (Remineralisation) unter Bildung von säurefesterem Fluorapatit. Zusätzlich hemmt Fluorid den Zuckerstoffwechsel der Plaquebakterien. Die Schutzwirkung beruht vor allem auf dem direkten Kontakt mit den Zähnen.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen mit Schwellungen im Mund (Fluoridlack, Kolophonium)","Asthmaanfälle bei Menschen mit Asthma (Fluoridlack)"],"unbekannt":["Zahnfluorose (weissliche bis bräunliche Flecken im Zahnschmelz) bei zu hoher Fluoridzufuhr während der Zahnentwicklung","Übelkeit, Erbrechen und Magenbeschwerden nach Verschlucken grösserer Mengen","Reizung oder Abschuppung der Mundschleimhaut (Zahngel)","Skelettfluorose (Knochenveränderungen) bei langdauernder Überdosierung"]},"schwangerschaft":"Die lokale Anwendung (Zahngel, Fluoridlack) in üblicher Menge ist vertretbar. Fluoridtabletten nur auf ärztlichen oder zahnärztlichen Rat; ein Nutzen für die Zähne des Kindes ist nicht belegt.","stillzeit":"Fluorid geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung in der Stillzeit ist möglich.","hinweise":["In der Schweiz ist fluoridiertes Speisesalz verbreitet: Fluoridtabletten nur nach Rücksprache mit Zahnärztin, Arzt oder Apotheke geben.","Fluoridtabletten langsam im Mund zergehen lassen, damit das Fluorid direkt auf die Zähne wirkt.","Zahngel nur einmal pro Woche verwenden, nach dem Einbürsten ausspucken und nicht schlucken.","Nach dem Auftragen von Fluoridlack einige Stunden nichts Hartes essen und die Zähne erst am nächsten Tag putzen."],"darreichung":["Tabletten (zum Lutschen)","Zahngel","Fluoridlack (Anwendung in der Zahnarztpraxis)"]},"natriumglycerophosphat":{"wirkmechanismus":"Liefert Phosphat, das der Körper für Energiestoffwechsel, Knochen und Zellmembranen braucht. Glycerophosphat wird im Blut durch alkalische Phosphatasen in anorganisches Phosphat und Glycerol gespalten. Weil das Phosphat organisch gebunden ist, lässt es sich in Ernährungslösungen besser mit Calcium mischen als anorganische Phosphatsalze.","nebenwirkungen":{"unbekannt":["Bei Überdosierung oder eingeschränkter Nierenfunktion: Hyperphosphatämie (erhöhtes Phosphat)","Bei Überdosierung: Hypokalzämie (Calciummangel) mit Krämpfen"]},"schwangerschaft":"Keine Daten; im Rahmen einer notwendigen parenteralen Ernährung nach ärztlicher Abwägung anwendbar.","stillzeit":"Keine Daten; im Rahmen einer notwendigen parenteralen Ernährung nach ärztlicher Abwägung anwendbar.","hinweise":["Nur als Zusatz zu Infusions- oder Ernährungslösungen verdünnt verabreichen, nie unverdünnt.","Phosphat-, Calcium- und Natriumwerte im Blut regelmässig kontrollieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"natriumhydrogencarbonat":{"wirkmechanismus":"Neutralisiert überschüssige Säure im Blut. Bicarbonat ist der wichtigste Puffer des Körpers: Es bindet Wasserstoff-Ionen, wobei Wasser und Kohlendioxid entstehen, das über die Lunge abgeatmet wird. Dadurch steigen pH-Wert und Bicarbonatspiegel im Blut; eine ausreichende Atmung ist Voraussetzung. Über die Niere ausgeschiedenes Bicarbonat macht den Urin basisch, wodurch schwache Säuren wie Salicylate oder Barbiturate besser ausgeschieden werden. Die magensaftresistenten Kapseln geben den Wirkstoff erst im Dünndarm frei, damit im Magen kein Gas entsteht.","nebenwirkungen":{"unbekannt":["Blähungen, Aufstossen, Bauchschmerzen (Kapseln)","Metabolische Alkalose (zu basisches Blut) bei Überdosierung","Hypernatriämie, Überwässerung und Ödeme","Hypokaliämie (Kaliummangel)","Muskelkrämpfe und Tetanie durch Abfall des freien Calciums","Infusion: Venenreizung, Gewebeschäden bei Paravasat"]},"schwangerschaft":"Bei klarer Indikation anwendbar; wegen der Natriumbelastung Vorsicht bei Ödemen und Präeklampsie.","stillzeit":"Kann angewendet werden.","hinweise":["Kapseln unzerkaut mit Flüssigkeit schlucken, nicht öffnen.","Natriumgehalt bei natriumarmer Diät, Herzschwäche oder Bluthochdruck beachten.","Säure-Basen-Haushalt (Blutgasanalyse) und Elektrolyte regelmässig kontrollieren lassen.","Konzentrierte Infusionslösung (8,4 %) möglichst über eine grosse oder zentrale Vene geben."],"darreichung":["Magensaftresistente Weichkapseln","Infusionslösung (z. B. 4,2 % und 8,4 %)"]},"natriumphenylbutyrat":{"wirkmechanismus":"Eröffnet dem Körper einen Ersatzweg, um überschüssigen Stickstoff loszuwerden, wenn der Harnstoffzyklus nicht funktioniert. Natriumphenylbutyrat ist eine Vorstufe (Prodrug) und wird rasch zu Phenylacetat umgewandelt. Phenylacetat verbindet sich mit der stickstoffreichen Aminosäure Glutamin zu Phenylacetylglutamin, das über die Niere ausgeschieden wird. Pro Molekül werden so zwei Stickstoffatome entfernt – wie beim Harnstoff –, was Ammoniak- und Glutaminspiegel im Blut senkt.","nebenwirkungen":{"sehrHaeufig":["Ausbleiben oder Unregelmässigkeit der Monatsblutung (Amenorrhö)"],"haeufig":["Appetitminderung","Geschmacksstörung, unangenehmer Körpergeruch","Bauchschmerzen, Übelkeit, Erbrechen, Verstopfung","Kopfschmerzen, Synkope (Ohnmacht)","Depression, Reizbarkeit","Blutbildveränderungen (Anämie, Mangel an Blutplättchen oder weissen Blutkörperchen)","Störungen des Säure-Basen- und Elektrolythaushalts (z. B. metabolische Azidose, Hypokaliämie), renale tubuläre Azidose","Ödeme (Wassereinlagerungen), Hautausschlag"],"gelegentlich":["Aplastische Anämie (Versagen der Blutbildung)","Blutergüsse (Ekchymosen)","Herzrhythmusstörungen","Gastritis, Magengeschwür, Rektalblutung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Haarausfall"]},"schwangerschaft":"Kontraindiziert (im Tierversuch Schädigung des sich entwickelnden Gehirns). Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Auf die Mahlzeiten des Tages verteilt einnehmen; das Granulat kann mit fester Nahrung oder mit Flüssigkeit gemischt werden.","Eiweissarme Diät und allfällige Ergänzungen (z. B. Aminosäuren) nach Anweisung des Stoffwechselzentrums weiterführen.","Regelmässige Kontrollen von Ammoniak, Aminosäuren, Elektrolyten (v. a. Kalium) und Blutbild."],"darreichung":["Tabletten","Granulat"]},"natriumphosphat":{"wirkmechanismus":"Löst rasch den Stuhlgang aus, indem die Lösung Wasser in den Enddarm zieht. Die stark konzentrierte (hypertone) Phosphatlösung bindet osmotisch Wasser im Rektum und Sigmoid, weicht den Stuhl auf und dehnt die Darmwand; der Dehnungsreiz löst den Entleerungsreflex meist innerhalb von 2 bis 15 Minuten aus. Ein kleiner Teil des Natriums und Phosphats wird über die Darmschleimhaut aufgenommen – bei längerem Verbleiben im Darm, eingeschränkter Nierenfunktion oder bei Kleinkindern kann dies zu gefährlichen Elektrolytstörungen führen.","nebenwirkungen":{"sehrSelten":["Hyperphosphatämie (zu viel Phosphat), Hypokalzämie (Calciummangel), Hypernatriämie, Hypokaliämie","Dehydratation (Austrocknung) und metabolische Azidose (Übersäuerung)","Überempfindlichkeitsreaktionen"],"unbekannt":["Brennen, Reizung oder Schmerzen am After","Bauchkrämpfe, Blähbauch, Übelkeit","Verletzung der Enddarmschleimhaut bei unsachgemässem Einführen","Krampfanfälle oder Herzrhythmusstörungen bei schweren Elektrolytstörungen (z. B. nach Überdosierung oder wenn das Klistier nicht ausgeschieden wird)"]},"schwangerschaft":"Kurzfristige Anwendung nach Rücksprache möglich; wird auch zur Darmentleerung vor der Geburt eingesetzt.","stillzeit":"Natrium und Phosphat können in die Muttermilch übergehen; nur nach Rücksprache anwenden – vorsichtshalber kann die Milch während 24 Stunden abgepumpt und verworfen werden.","hinweise":["Nicht mehr als ein Klistier innerhalb von 24 Stunden und nicht über längere Zeit anwenden.","Erfolgt nach dem Einlauf innert etwa 15 Minuten keine Entleerung, ärztlichen Rat einholen (Gefahr von Elektrolytstörungen).","Liegend auf der linken Seite mit angezogenen Knien vorsichtig einführen; vor und nach der Anwendung genügend trinken."],"darreichung":["Rektallösung (Klistier, Einlauf)"]},"natriumpicosulfat":{"wirkmechanismus":"Regt den Dickdarm an und sorgt für weicheren Stuhl. Natriumpicosulfat ist eine Vorstufe (Prodrug), die unverändert in den Dickdarm gelangt und dort von Darmbakterien zum wirksamen BHPM (Bis-(p-hydroxyphenyl)-pyridyl-2-methan, wie bei Bisacodyl) gespalten wird. Dieses verstärkt die Peristaltik und fördert die Ansammlung von Wasser und Salzen im Darm; die Wirkung tritt nach 6–12 Stunden ein. In der Kombination zur Darmreinigung bildet sich zusätzlich Magnesiumcitrat, das als osmotisches Abführmittel Wasser in den Darm zieht.","nebenwirkungen":{"haeufig":["Durchfall"],"gelegentlich":["Bauchbeschwerden, Bauchschmerzen, Bauchkrämpfe","Übelkeit, Erbrechen","Schwindel"],"unbekannt":["Überempfindlichkeitsreaktionen mit Hautausschlag, Juckreiz oder Angioödem","Kurze Ohnmacht (Synkope)","Darmreinigung: Kopfschmerzen, Schmerzen im Analbereich","Darmreinigung: Natriummangel (Hyponatriämie), Kaliummangel, Magnesiumüberschuss, sehr selten mit Krampfanfällen"]},"schwangerschaft":"Es sind keine schädlichen Wirkungen bekannt; dennoch nur nach ärztlicher Rücksprache anwenden, wenn Ernährungsmassnahmen nicht ausreichen.","stillzeit":"Der Wirkstoff geht nicht nennenswert in die Muttermilch über; Anwendung in der Stillzeit möglich.","hinweise":["Abends einnehmen, die Wirkung tritt am nächsten Morgen ein (nach 6–12 Stunden).","Abführmittel nur kurzzeitig anwenden; bei anhaltender Verstopfung ärztlich abklären lassen.","Bei der Darmreinigung genau nach Anleitung reichlich klare Flüssigkeit trinken, um Austrocknung und Salzverlust zu vermeiden."],"darreichung":["Tropfen","Tabletten","Pulver zur Herstellung einer Lösung (Kombination)"]},"nebivolol":{"wirkmechanismus":"Senkt Puls und Blutdruck, indem es die Wirkung der Stresshormone am Herzen abschwächt und zusätzlich die Blutgefässe weitet. Nebivolol blockiert hoch selektiv und kompetitiv die Beta-1-Adrenozeptoren des Herzens und senkt so Herzfrequenz und Kontraktionskraft. Zusätzlich fördert es die Freisetzung von Stickstoffmonoxid (NO) aus der Gefässinnenwand, was die Gefässe erweitert und den peripheren Widerstand senkt. Nebivolol wird über CYP2D6 abgebaut; bei langsamen Metabolisierern sind die Spiegel höher, die Wirkung ist aber vergleichbar.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel (bei Herzschwäche sehr häufig)","Kribbeln (Parästhesien)","Müdigkeit","Atemnot (Dyspnoe)","Verstopfung, Übelkeit, Durchfall","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Bradykardie (langsamer Puls; bei Herzschwäche sehr häufig)","Verschlechterung einer Herzschwäche, verlangsamte AV-Überleitung bzw. AV-Block","Hypotonie (tiefer Blutdruck)","Bronchospasmus (Verkrampfung der Atemwege)","Albträume, Depression","Sehstörungen","Verstärkte Schaufensterkrankheit (Claudicatio intermittens)","Juckreiz, Hautausschlag, Erektionsstörungen, Verdauungsbeschwerden, Blähungen, Erbrechen"],"sehrSelten":["Synkope (Ohnmacht)","Verschlechterung einer Psoriasis"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Überempfindlichkeitsreaktionen, Nesselsucht"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: Betablocker können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes hemmen. Neugeborene in den ersten Lebenstagen auf langsamen Puls und Unterzuckerung überwachen.","stillzeit":"Nicht empfohlen; ob Nebivolol in die Muttermilch übergeht, ist beim Menschen nicht bekannt (im Tierversuch ja).","hinweise":["Nicht abrupt absetzen – Gefahr von Blutdruckanstieg, Herzrasen und Angina-pectoris-Anfällen; ein Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Zu Beginn können Schwindel und Müdigkeit auftreten; Vorsicht beim Autofahren.","Täglich etwa zur gleichen Zeit einnehmen, unabhängig von den Mahlzeiten.","Vor Operationen und Narkosen die Einnahme angeben."],"darreichung":["Tabletten"]},"nelarabin":{"wirkmechanismus":"Tötet gezielt bösartige T-Lymphozyten ab. Nelarabin ist eine Vorstufe (Prodrug), die durch das Enzym Adenosindesaminase rasch zu Ara-G umgewandelt wird. In der Zelle entsteht daraus das wirksame Ara-GTP, das sich besonders in T-Zellen anreichert, in die DNA eingebaut wird und die DNA-Synthese hemmt. Die Folge ist der programmierte Zelltod (Apoptose).","nebenwirkungen":{"sehrHaeufig":["Infektionen, febrile Neutropenie","Neutropenie, Thrombozytopenie, Anämie, Leukopenie","Schläfrigkeit, Schwindel, Kopfschmerzen","Periphere Neuropathie mit Kribbeln, Taubheits- und Schwächegefühl","Atemnot, Husten","Übelkeit, Erbrechen, Durchfall, Verstopfung","Muskelschmerzen","Ödeme, Fieber, Müdigkeit, Schwäche"],"haeufig":["Krampfanfälle","Verwirrtheit, Gedächtnisstörungen","Gleichgewichtsstörungen (Ataxie), Zittern, Geschmacksstörungen","Verschwommenes Sehen","Tumorlysesyndrom","Tiefer Blutdruck, Pleuraerguss (Flüssigkeit im Brustfell)","Mundschleimhautentzündung, Bauchschmerzen","Erhöhte Leberwerte, Bilirubin und Kreatinin"],"selten":["Demyelinisierung und aufsteigende Lähmungen ähnlich dem Guillain-Barré-Syndrom"],"unbekannt":["Rhabdomyolyse (Muskelzerfall), erhöhte Kreatinkinase"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; im Tierversuch fruchtschädigend. Frauen und Männer müssen während und einige Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Bei Kribbeln, Taubheit oder Schwäche in Armen oder Beinen, Verwirrtheit oder Krampfanfällen sofort das Behandlungsteam informieren.","Schläfrigkeit und Verwirrtheit beeinträchtigen die Fahrtüchtigkeit: während und nach der Behandlung nicht Auto fahren oder Maschinen bedienen.","Ausreichend trinken; Blutbild wird regelmässig kontrolliert."],"darreichung":["Infusionslösung"]},"nemolizumab":{"wirkmechanismus":"Unterbricht das Juckreiz-Signal und dämpft die Entzündung der Haut. Nemolizumab ist ein humanisierter Antikörper, der an den Interleukin-31-Rezeptor A (IL-31RA) bindet und so die Wirkung von IL-31 blockiert. IL-31 reizt Nervenfasern der Haut und löst Juckreiz aus; zudem fördert es Entzündung und Störungen der Hautbarriere. Der Juckreiz lässt häufig schon in den ersten Behandlungswochen nach.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Ekzem bzw. Aufflammen der Neurodermitis"],"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Nesselsucht, Gesichtsschwellung)","Reaktionen an der Injektionsstelle"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Nemolizumab in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Im Kühlschrank lagern und vor der Zubereitung auf Raumtemperatur kommen lassen; die Anleitung des Fertigpens genau befolgen.","Bei Atemnot, Schwellung von Gesicht oder Lippen nach der Injektion sofort ärztliche Hilfe holen.","Bei Neurodermitis werden in der Regel begleitend Kortison- oder Calcineurinhemmer-Cremes verwendet."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (Fertigpen)"]},"neratinib":{"wirkmechanismus":"Blockiert Wachstumssignale in Brustkrebszellen mit zu vielen HER2-Rezeptoren. Neratinib bindet irreversibel an die Tyrosinkinasen von EGFR (HER1), HER2 und HER4 und hemmt so deren Aktivierung. Dadurch werden die nachgeschalteten Signalwege (MAPK, AKT) unterbrochen und die Zellteilung gebremst.","nebenwirkungen":{"sehrHaeufig":["Durchfall (oft schwer)","Übelkeit, Erbrechen, Bauchschmerzen","Stomatitis (Mundschleimhautentzündung)","Müdigkeit","Hautausschlag","Appetitlosigkeit","Muskelkrämpfe"],"haeufig":["Dehydratation (Flüssigkeitsmangel)","Dyspepsie (Verdauungsbeschwerden), Blähbauch, Mundtrockenheit","Nagelveränderungen, trockene Haut","Erhöhte Leberwerte","Gewichtsabnahme, Geschmacksstörungen, Nasenbluten","Erhöhte Nierenwerte (Kreatinin)"],"gelegentlich":["Nierenversagen","Erhöhtes Bilirubin"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und bis 1 Monat, Männer bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen, möglichst morgens.","In den ersten 2 Monaten vorbeugend Loperamid wie verordnet einnehmen; ausreichend trinken und schweren Durchfall sofort melden.","Grapefruit und Granatapfel meiden.","Leberwerte regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"netupitant-palonosetron":{"wirkmechanismus":"Verhindert Übelkeit und Erbrechen über zwei Wege gleichzeitig. Netupitant blockiert im Gehirn die NK1-Rezeptoren für den Botenstoff Substanz P, die vor allem für das verzögerte Erbrechen in den Tagen nach der Chemotherapie verantwortlich sind. Palonosetron blockiert 5-HT3-Rezeptoren im Darm und im Brechzentrum und wirkt vor allem gegen das akute Erbrechen. Beide Wirkstoffe werden sehr langsam ausgeschieden, deshalb genügt eine einzige Kapsel pro Chemotherapiezyklus. Netupitant hemmt zudem das Abbauenzym CYP3A4 mässig.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Obstipation (Verstopfung)","Müdigkeit (Fatigue)"],"gelegentlich":["Appetitlosigkeit","Schlaflosigkeit","Schwindel","Schluckauf","Verdauungsbeschwerden, Bauchschmerzen, Blähungen","Haarausfall, Nesselsucht","Erhöhte Leberwerte","EKG-Veränderungen wie AV-Block 1. Grades und QT-Verlängerung"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie","Serotonin-Syndrom (vor allem zusammen mit serotonergen Mitteln)"]},"schwangerschaft":"Kontraindiziert. Bei Frauen im gebärfähigen Alter wird vor der Einnahme eine Schwangerschaft ausgeschlossen; bis einen Monat danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis einen Monat nach der Einnahme nicht stillen.","hinweise":["Wird einmalig vor Beginn der Chemotherapie eingenommen, unabhängig von den Mahlzeiten.","Alle anderen Medikamente, auch pflanzliche wie Johanniskraut, dem Behandlungsteam angeben: Netupitant beeinflusst deren Abbau noch mehrere Tage."],"darreichung":["Hartkapseln"]},"nevirapin":{"wirkmechanismus":"Hemmt die Vermehrung des HI-Virus. Nevirapin bindet direkt an eine Tasche der Reversen Transkriptase von HIV-1 nahe dem aktiven Zentrum und verändert deren Form, sodass das Enzym die virale RNA nicht mehr in DNA umschreiben kann. Gegen HIV-2 wirkt es nicht. Nevirapin induziert die Leberenzyme CYP3A4 und CYP2B6 und beschleunigt damit auch seinen eigenen Abbau.","nebenwirkungen":{"sehrHaeufig":["Hautausschlag"],"haeufig":["Granulozytopenie (Mangel an weissen Blutkörperchen)","Überempfindlichkeitsreaktionen","Kopfschmerzen","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Hepatitis, erhöhte Leberwerte","Müdigkeit, Fieber"],"gelegentlich":["Anämie","Gelbsucht","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie, Angioödem, Nesselsucht","Gelenk- und Muskelschmerzen"],"selten":["Fulminante Hepatitis, Leberversagen","DRESS (schwere Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden; bei Frauen mit mehr als 250 CD4-Zellen/µl erhöhtes Risiko für Leberschäden beachten.","stillzeit":"Menschen mit HIV wird generell vom Stillen abgeraten; allenfalls nach eingehender Beratung durch die HIV-Fachperson.","hinweise":["Die Behandlung beginnt mit einer 14-tägigen Einschleichphase mit niedrigerer Dosis – diese genau einhalten; erhöht wird erst, wenn kein Ausschlag aufgetreten ist.","In den ersten 18 Wochen werden die Leberwerte engmaschig kontrolliert.","Bei Ausschlag mit Fieber, Blasen, Befall der Mundschleimhaut, Gelbsucht oder starker Müdigkeit sofort ärztliche Hilfe holen.","Hormonale Verhütung immer mit Kondom ergänzen."],"darreichung":["Tabletten","Retardtabletten"]},"nifedipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Gefässmuskulatur entspannt und die Arterien weitet. Nifedipin blockiert L-Typ-Calciumkanäle in der glatten Muskulatur der peripheren Arterien und der Herzkranzgefässe; der Gefässwiderstand sinkt, die Herzkranzgefässe werden erweitert und Gefässkrämpfe verhindert. Die Retardtablette gibt den Wirkstoff über 24 Stunden gleichmässig frei und mildert so die bei rasch freigesetztem Nifedipin typische reflektorische Pulsbeschleunigung. Nifedipin wird in Darm und Leber über CYP3A4 abgebaut.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Ödeme (Wassereinlagerungen, vor allem an den Beinen)","Flush (Gesichtsrötung mit Wärmegefühl)","Verstopfung","Unwohlsein"],"gelegentlich":["Herzklopfen, beschleunigter Puls","Hypotonie (tiefer Blutdruck), Synkope (Ohnmacht)","Schwindel, Benommenheit, Migräne, Zittern, Schlafstörungen, Angstreaktionen","Übelkeit, Bauchschmerzen, Verdauungsstörungen, Blähungen, Mundtrockenheit","Allergische Reaktionen, allergisches Ödem bzw. Angioödem","Erhöhte Leberwerte","Muskelkrämpfe, Gelenkschwellung","Vermehrtes Wasserlassen, Erektionsstörungen, Sehstörungen, Nasenbluten"],"selten":["Juckreiz, Nesselsucht, Hautausschlag","Kribbeln oder Missempfindungen (Parästhesien)","Zahnfleischwucherung (Gingivahyperplasie)"],"unbekannt":["Agranulozytose, Leukopenie (Mangel an weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Brustschmerzen (Angina pectoris)","Darmverschluss, Bezoar (Tablettenklumpen im Verdauungstrakt), Schluckbeschwerden, Erbrechen","Gelbsucht (Ikterus)","Toxische epidermale Nekrolyse, Lichtempfindlichkeit","Hyperglykämie (erhöhter Blutzucker)","Atemnot, Lungenödem"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; im Tierversuch fruchtschädigend. Zusammen mit Magnesiumsulfat i. v. droht ein übermässiger Blutdruckabfall.","stillzeit":"Nifedipin geht in die Muttermilch über; während der Behandlung wird vom Stillen abgeraten.","hinweise":["Retardtablette unzerkaut mit Flüssigkeit schlucken, nicht teilen; die leere Tablettenhülle kann im Stuhl sichtbar sein – das ist normal.","Grapefruit und Grapefruitsaft meiden.","Bei neuen oder stärkeren Brustschmerzen nach Behandlungsbeginn sofort ärztlich melden.","Zu Beginn sind Schwindel und Kopfschmerzen möglich; Vorsicht beim Autofahren, besonders zusammen mit Alkohol."],"darreichung":["Retardtabletten (Tabletten mit verzögerter Wirkstofffreisetzung)"]},"nikotin":{"wirkmechanismus":"Ersetzt beim Rauchstopp einen Teil des Nikotins aus dem Tabak und lindert so Entzugssymptome und Rauchverlangen – ohne Teer, Kohlenmonoxid und die übrigen Schadstoffe des Rauchs. Nikotin ist ein Agonist an nikotinischen Acetylcholinrezeptoren im Gehirn, im vegetativen Nervensystem und an der Muskulatur; im Belohnungssystem setzt es Dopamin frei. Aus Pflaster, Kaugummi, Lutschtablette oder Spray wird es langsamer und in tieferer Konzentration aufgenommen als beim Rauchen, was das Abhängigkeitspotenzial senkt.","nebenwirkungen":{"sehrHaeufig":["Hautreizung an der Pflasterstelle (Rötung, Juckreiz)","Kopfschmerzen","Übelkeit","Schluckauf, Reizung von Mund und Rachen (Kaugummi, Lutschtablette, Spray, Inhalator)"],"haeufig":["Schwindel","Geschmacksstörungen, Kribbeln im Mund","Erbrechen, Durchfall, Bauchschmerzen, Blähungen, Dyspepsie (Verdauungsbeschwerden)","Mundtrockenheit, vermehrter Speichelfluss, Entzündung der Mundschleimhaut","Schlafstörungen und lebhafte Träume (Pflaster)","Husten","Müdigkeit","Überempfindlichkeitsreaktionen"],"gelegentlich":["Herzklopfen, Herzrasen","Hautrötung (Flush), Bluthochdruck","Bronchospasmus (Verkrampfung der Atemwege), Atemnot","Nesselsucht, Hautausschlag, vermehrtes Schwitzen","Kieferschmerzen, Muskelschmerzen","Schwäche, Brustbeschwerden"],"selten":["Vorhofflimmern"],"unbekannt":["Anaphylaxie, Angioödem","Krampfanfälle","Verschwommenes Sehen"]},"schwangerschaft":"Ein Rauchstopp ohne Medikamente ist anzustreben. Gelingt das nicht, ist eine Nikotinersatztherapie nach ärztlicher Rücksprache besser als Weiterrauchen; Kaugummi, Lutschtablette oder Spray sind dem Pflaster vorzuziehen.","stillzeit":"Nikotin geht in die Muttermilch über; nur nach ärztlicher Rücksprache und kurz wirksame Formen möglichst unmittelbar nach dem Stillen anwenden.","hinweise":["Kaugummi langsam kauen und zwischendurch in der Backe «parken»; 15 Minuten vor und während der Anwendung keine sauren Getränke wie Kaffee oder Fruchtsaft (vermindern die Aufnahme).","Für Kinder unzugänglich aufbewahren und gebrauchte Pflaster zusammengefaltet entsorgen – schon kleine Mengen können für Kinder lebensgefährlich sein.","Pflaster täglich an einer anderen Hautstelle aufkleben; bei Schlafstörungen das Pflaster vor dem Schlafengehen entfernen.","Nach dem Rauchstopp können die Spiegel bestimmter Medikamente (z. B. Clozapin, Theophyllin) steigen – Ärztin oder Arzt informieren."],"darreichung":["Transdermale Pflaster","Kaugummis","Lutschtabletten","Sublingualtabletten","Mundspray","Inhalator"]},"nilotinib":{"wirkmechanismus":"Blockiert gezielt das krankhafte Enzym, das die Leukämiezellen bei CML wachsen lässt. Nilotinib bindet an die inaktive Form der BCR-ABL-Tyrosinkinase und hemmt sie deutlich stärker als Imatinib; es wirkt gegen die meisten Imatinib-resistenten Mutationen, nicht aber gegen T315I. Zusätzlich hemmt es KIT und PDGF-Rezeptoren.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen, Müdigkeit","Übelkeit, Verstopfung, Bauchschmerzen","Hautausschlag, Juckreiz, Haarausfall","Muskel- und Gelenkschmerzen","Mangel an Blutplättchen, weissen und roten Blutkörperchen","Erhöhte Bilirubin-, Leber- und Lipasewerte im Blut"],"haeufig":["QT-Verlängerung im EKG, Herzrhythmusstörungen, Herzklopfen","Angina pectoris (Brustenge)","Bluthochdruck, Hitzewallungen","Erhöhter Blutzucker und erhöhte Blutfette","Schwindel, Schlafstörungen"],"gelegentlich":["Herzinfarkt, Herzschwäche","Periphere arterielle Verschlusskrankheit (Durchblutungsstörung der Beine)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Plötzlicher Herztod (vor allem bei vorbehandelten Patienten mit Herzrisiken)"],"unbekannt":["Durchblutungsstörungen des Gehirns, Schlaganfall","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während und bis 2 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und 2 Wochen danach nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden nüchtern einnehmen: frühestens 2 Stunden nach und mindestens 1 Stunde vor dem Essen – Nahrung erhöht die Aufnahme und damit das Risiko für Herzrhythmusstörungen.","Keine Grapefruit, kein Grapefruitsaft und kein Johanniskraut.","Regelmässige Kontrollen von EKG, Blutbild, Elektrolyten, Leber- und Lipasewerten, Blutzucker und Blutfetten.","Brustschmerzen, Ohnmacht, Lähmungen oder Schmerzen in den Beinen sofort ärztlich abklären."],"darreichung":["Hartkapseln"]},"nimodipin":{"wirkmechanismus":"Erweitert vor allem die Blutgefässe des Gehirns und verbessert so dessen Durchblutung. Nimodipin blockiert spannungsabhängige L-Typ-Calciumkanäle in der glatten Gefässmuskulatur und verhindert den Calciumeinstrom, der für die Gefässverengung nötig ist. Weil es sehr fettlöslich ist, passiert es die Blut-Hirn-Schranke und wirkt bevorzugt an den Hirnarterien.","nebenwirkungen":{"gelegentlich":["Hypotonie (Blutdruckabfall)","Gefässerweiterung mit Flush (Hautrötung, Wärmegefühl)","Kopfschmerzen","Tachykardie (Herzrasen)","Übelkeit","Allergische Reaktionen, Hautausschlag","Thrombozytopenie (Mangel an Blutplättchen)"],"selten":["Bradykardie (langsamer Puls)","Ileus (Darmlähmung)","Vorübergehender Anstieg der Leberwerte","Reaktionen und Venenentzündung an der Infusionsstelle"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach sorgfältiger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Nimodipin geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Kein Grapefruitsaft während der Behandlung mit Tabletten (erhöht die Nimodipin-Spiegel).","Der Blutdruck wird regelmässig kontrolliert; bei Schwindel oder Benommenheit kein Fahrzeug lenken.","Die Infusion wird im Spital über einen zentralen Venenkatheter gegeben, vor direktem Sonnenlicht geschützt; sie enthält Alkohol."],"darreichung":["Filmtabletten","Infusionslösung"]},"nintedanib":{"wirkmechanismus":"Bremst die Vernarbung (Fibrosierung) des Lungengewebes. Nintedanib hemmt mehrere Rezeptor-Tyrosinkinasen – die Rezeptoren für die Wachstumsfaktoren PDGF, FGF und VEGF – sowie Kinasen der Src-Familie. Dadurch werden Vermehrung, Wanderung und Umwandlung von Fibroblasten zu Myofibroblasten gehemmt, die bei Lungenfibrosen übermässig Bindegewebe bilden. Die Hemmung des VEGF-Signalwegs erklärt Nebenwirkungen wie Blutungen und Blutdruckanstieg.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Bauchschmerzen","Erhöhte Leberwerte"],"haeufig":["Erbrechen","Appetitlosigkeit, Gewichtsverlust","Blutungen (z. B. Nasenbluten)","Bluthochdruck"],"gelegentlich":["Herzinfarkt","Pankreatitis (Bauchspeicheldrüsenentzündung)","Kolitis (Dickdarmentzündung)","Thrombozytopenie (Mangel an Blutplättchen)","Arzneimittelbedingter Leberschaden, erhöhtes Bilirubin","Hautausschlag, Juckreiz, Haarausfall","Proteinurie (Eiweiss im Urin)"],"unbekannt":["Aneurysmen und Arteriendissektionen (Gefässaussackungen und -einrisse)","Magen-Darm-Perforation (Darmdurchbruch)","Nierenversagen"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter brauchen vor Beginn einen Schwangerschaftstest und müssen während sowie mindestens 3 Monate nach der Behandlung hochwirksam verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden mit einer Mahlzeit unzerkaut mit Wasser schlucken; Kapseln nicht öffnen.","Bei Durchfall früh reichlich trinken und ein Mittel gegen Durchfall (z. B. Loperamid) nach ärztlicher Anweisung einnehmen.","Die Leberwerte werden in den ersten 3 Monaten monatlich, danach regelmässig kontrolliert.","Wegen möglichem Durchfall oder Erbrechen bei hormonaler Verhütung zusätzlich ein Kondom verwenden."],"darreichung":["Weichkapseln"]},"nipocalimab":{"wirkmechanismus":"Senkt die Menge an Antikörpern im Blut, darunter die Autoantikörper, die bei Myasthenia gravis die Signalübertragung vom Nerv auf den Muskel stören. Nipocalimab ist ein vollständig humaner monoklonaler Antikörper, der den neonatalen Fc-Rezeptor (FcRn) blockiert. Dieser Rezeptor schützt IgG-Antikörper normalerweise vor dem Abbau und führt sie in den Blutkreislauf zurück; wird er gehemmt, werden IgG-Antikörper schneller abgebaut und ihr Spiegel sinkt deutlich. Andere Antikörperklassen werden nicht vermindert.","nebenwirkungen":{"sehrHaeufig":["Atemwegsinfektionen","Periphere Ödeme (Wassereinlagerungen, v. a. in den Beinen)","Muskelkrämpfe"],"haeufig":["Harnwegsinfektion","Herpes-Infektionen (Gürtelrose, Lippenherpes)","Bauchschmerzen, Durchfall","Rückenschmerzen","Fieber"],"unbekannt":["Überempfindlichkeitsreaktionen, Angioödem, Anaphylaxie","Infusionsbedingte Reaktionen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Nipocalimab vermindert den Übertritt mütterlicher Antikörper auf das Kind; Impfungen des Säuglings, besonders Lebendimpfungen, ärztlich besprechen.","stillzeit":"Keine ausreichenden Daten; Nutzen des Stillens und der Behandlung ärztlich abwägen.","hinweise":["Wird als Infusion in Klinik oder Praxis verabreicht; danach auf allergische Reaktionen achten.","Impfstatus vor Beginn überprüfen; keine Lebendimpfungen während der Behandlung.","Fieber oder andere Infektzeichen ärztlich melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"niraparib":{"wirkmechanismus":"Verhindert, dass Krebszellen Schäden an ihrem Erbgut reparieren. Niraparib hemmt die Enzyme PARP-1 und PARP-2, die Einzelstrangbrüche der DNA beheben, und hält PARP zusätzlich an der DNA fest («PARP-Trapping»). Tumorzellen mit gestörter homologer Rekombination, z. B. bei BRCA-Mutation, können die daraus entstehenden Doppelstrangbrüche nicht reparieren und sterben ab (synthetische Letalität).","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie (Mangel an Blutplättchen), Anämie, Neutropenie","Übelkeit, Erbrechen, Verstopfung","Müdigkeit, Schwäche","Kopfschmerzen, Schwindel","Schlaflosigkeit","Bluthochdruck","Appetitlosigkeit","Harnwegsinfekte"],"haeufig":["Myelodysplastisches Syndrom und akute myeloische Leukämie (Blutkrebs)","Herzrasen, Herzklopfen","Nasenbluten","Lichtempfindlichkeit der Haut, Hautausschlag","Erhöhte Leberwerte","Depression, Angst","Mundschleimhautentzündung"],"gelegentlich":["Pneumonitis (Entzündung des Lungengewebes)","Panzytopenie (Mangel aller Blutzellen)","Verwirrtheit, Halluzinationen"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Hypertensive Krise"]},"schwangerschaft":"Nicht anwenden. Schwangerschaftstest vor Beginn; Frauen im gebärfähigen Alter verhüten während und bis 6 Monate nach der letzten Dosis.","stillzeit":"Kontraindiziert; während der Behandlung und bis 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich etwa zur gleichen Zeit einnehmen; Einnahme vor dem Schlafengehen kann Übelkeit vermindern.","Blutbild und Blutdruck regelmässig kontrollieren lassen.","Auf Sonnenschutz achten (Lichtempfindlichkeit möglich).","Akeega auf nüchternen Magen einnehmen (mindestens 1 Stunde vor oder 2 Stunden nach dem Essen)."],"darreichung":["Filmtabletten"]},"nirmatrelvir-ritonavir":{"wirkmechanismus":"Hemmt die Vermehrung des Coronavirus SARS-CoV-2. Nirmatrelvir blockiert die Hauptprotease des Virus (Mpro, 3CL-Protease), die die viralen Polyproteine in funktionsfähige Einzelproteine zerschneidet; ohne diesen Schritt kann sich das Virus nicht vermehren. Ritonavir wirkt nicht gegen SARS-CoV-2, hemmt aber stark das Abbauenzym CYP3A4 und erhöht so die Nirmatrelvir-Spiegel. Diese CYP3A-Hemmung ist die Ursache der vielen Wechselwirkungen und hält nach Behandlungsende noch einige Tage an.","nebenwirkungen":{"haeufig":["Geschmacksstörung (Dysgeusie)","Durchfall","Kopfschmerzen","Übelkeit, Erbrechen"],"gelegentlich":["Bauchschmerzen","Bluthochdruck","Muskelschmerzen","Hautausschlag, Juckreiz","Überempfindlichkeitsreaktionen"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Unwohlsein"]},"schwangerschaft":"Nicht empfohlen, ausser der klinische Zustand erfordert die Behandlung. Frauen im gebärfähigen Alter sollen während der Behandlung wirksam verhüten (hormonale Verhütung ist abgeschwächt).","stillzeit":"Während der Behandlung und bis 48 Stunden nach der letzten Dosis nicht stillen.","hinweise":["Vor Beginn alle Medikamente, auch pflanzliche und rezeptfreie, mit Ärztin, Arzt oder Apotheke prüfen – viele Dauermedikamente müssen pausiert oder angepasst werden.","So früh wie möglich, spätestens 5 Tage nach Symptombeginn beginnen; 5 Tage lang zweimal täglich alle Tabletten einer Dosis zusammen einnehmen, mit oder ohne Essen, ganz schlucken.","Die Hemmung des Abbauenzyms hält nach der letzten Dosis noch 2–3 Tage an – pausierte Medikamente erst nach ärztlicher Anweisung wieder beginnen."],"darreichung":["Filmtabletten (Kombipackung)"]},"nirogacestat":{"wirkmechanismus":"Bremst das Wachstum von Desmoidtumoren, indem es ein Signal unterbricht, das die Tumorzellen zum Wachsen anregt. Nirogacestat hemmt reversibel die Gamma-Sekretase, ein Enzym, das den Notch-Rezeptor spaltet und dadurch aktiviert. Durch die Hemmung wird der Notch-Signalweg blockiert, der bei Desmoidtumoren zum Tumorwachstum beiträgt.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Bauchschmerzen","Eierstockschädigung (ausbleibende oder unregelmässige Menstruation, Wechseljahrsbeschwerden)","Hautausschlag, Haarausfall","Mundschleimhautentzündung (Stomatitis)","Müdigkeit, Kopfschmerzen","Husten, Atemnot, Infektionen der oberen Atemwege","Phosphat- und Kaliummangel","Erhöhte Leberwerte"],"haeufig":["Nicht-melanozytärer Hautkrebs (Basalzell- und Plattenepithelkarzinom)"]},"schwangerschaft":"Nicht anwenden (kann das ungeborene Kind schädigen). Frauen im gebärfähigen Alter müssen während und bis 1 Woche nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Grapefruit, Bitterorangen und Johanniskraut meiden.","Säureblocker (PPI, H2-Blocker) meiden.","Bei Durchfall früh mit dem verordneten Durchfallmittel beginnen und viel trinken.","Regelmässige Hautkontrollen und Laborkontrollen (Phosphat, Kalium, Leberwerte)."],"darreichung":["Filmtabletten"]},"nirsevimab":{"wirkmechanismus":"Gibt dem Säugling sofort fertige Abwehrstoffe gegen das RS-Virus, ohne dass das eigene Immunsystem diese erst bilden muss. Nirsevimab ist ein menschlicher monoklonaler Antikörper, der das Fusionsprotein (F-Protein) des RS-Virus in seiner Ausgangsform bindet und so das Eindringen des Virus in die Zellen verhindert. Durch eine Veränderung im Antikörper hält der Schutz mindestens 5 Monate an, sodass eine einzige Dosis für eine Saison genügt.","nebenwirkungen":{"gelegentlich":["Hautausschlag","Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerz)","Fieber"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nicht zutreffend – das Mittel ist für Säuglinge und Kleinkinder bestimmt.","stillzeit":"Nicht zutreffend – Stillen des behandelten Säuglings ist ohne Einschränkung möglich.","hinweise":["Eine einzelne Spritze vor oder während der RSV-Saison (Herbst/Winter); Neugeborene wenn möglich bereits kurz nach der Geburt.","Kann gleichzeitig mit den üblichen Säuglingsimpfungen gegeben werden.","Ersetzt nicht die Hygienemassnahmen; bei Atemnot oder Trinkschwäche des Säuglings trotzdem ärztlich abklären lassen."],"darreichung":["Fertigspritze (Injektionslösung, intramuskulär)"]},"nitisinon":{"wirkmechanismus":"Verhindert, dass bei der erblichen Tyrosinämie Typ 1 leber- und nierenschädigende Abbauprodukte entstehen. Nitisinon hemmt das Enzym 4-Hydroxyphenylpyruvat-Dioxygenase, das im Abbauweg der Aminosäure Tyrosin vor dem defekten Enzym (Fumarylacetoacetat-Hydrolase) liegt. Dadurch werden die giftigen Zwischenprodukte Maleyl- und Fumarylacetoacetat sowie Succinylaceton nicht mehr gebildet. Weil sich dafür Tyrosin im Blut anreichert, ist eine tyrosin- und phenylalaninarme Diät nötig.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Tyrosinspiegel im Blut (Laborbefund)"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Leukopenie und Granulozytopenie (Mangel an weissen Blutkörperchen)","Konjunktivitis (Bindehautentzündung)","Keratitis (Hornhautentzündung), Hornhauttrübung","Lichtscheu, Augenschmerzen"],"gelegentlich":["Leukozytose (Vermehrung weisser Blutkörperchen)","Blepharitis (Lidrandentzündung)","Juckreiz, Hautausschlag","Exfoliative Dermatitis (schuppende Hautentzündung)"]},"schwangerschaft":"Nur anwenden, wenn der Gesundheitszustand der Frau eine Behandlung erfordert; die Erfahrungen sind begrenzt.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Die tyrosin- und phenylalaninarme Diät strikt einhalten; Tyrosinspiegel im Blut regelmässig kontrollieren lassen.","Augenrötung, Augenschmerzen oder Lichtempfindlichkeit sofort ärztlich abklären lassen.","Regelmässige Kontrollen von Blutbild, Leberwerten und Alpha-Fetoprotein (Früherkennung von Leberkrebs).","Immer gleich einnehmen: entweder stets mit oder stets ohne Mahlzeit."],"darreichung":["Hartkapseln","Suspension zum Einnehmen"]},"nitrazepam":{"wirkmechanismus":"Macht schläfrig und beruhigt, indem es die Wirkung eines hemmenden Botenstoffs im Gehirn verstärkt. Nitrazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung von GABA. Es wird in der Leber vorwiegend durch Reduktion der Nitrogruppe und anschliessende Acetylierung zu unwirksamen Produkten abgebaut. Die Halbwertszeit beträgt rund einen Tag, bei älteren Menschen länger; Müdigkeit am Folgetag ist daher möglich.","nebenwirkungen":{"haeufig":["Müdigkeit und Benommenheit am Folgetag","Schwindel","Gangunsicherheit (Ataxie)","Verminderte Konzentration und Reaktionsfähigkeit"],"unbekannt":["Anterograde Amnesie (Erinnerungslücken für die Zeit nach der Einnahme)","Verwirrtheit, besonders bei älteren Menschen","Paradoxe Reaktionen (Unruhe, Erregung, Aggressivität, Albträume, Halluzinationen)","Muskelschwäche und Stürze","Kopfschmerzen, Sehstörungen","Atemdepression (Atemdämpfung)","Abhängigkeit, Entzugserscheinungen und Rebound-Schlaflosigkeit beim Absetzen","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft drohen beim Neugeborenen Atemprobleme, Muskelschlaffheit, Unterkühlung und Entzugssymptome.","stillzeit":"Nitrazepam geht in die Muttermilch über und kann beim Säugling zu Schläfrigkeit und Trinkschwäche führen – nicht anwenden bzw. abstillen.","hinweise":["Nur kurzfristig einnehmen (in der Regel höchstens wenige Wochen); bei längerer Einnahme droht Abhängigkeit.","Die Fahrtüchtigkeit kann auch am nächsten Tag eingeschränkt sein; keinen Alkohol trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anweisung schrittweise ausschleichen.","Ältere Menschen: erhöhte Sturzgefahr in der Nacht und am Folgetag."],"darreichung":["Tabletten"]},"nitrofurantoin":{"wirkmechanismus":"Tötet Bakterien in der Blase ab, wirkt aber kaum im übrigen Körper. Nitrofurantoin wird in den Bakterien durch bakterielle Nitroreduktasen zu reaktiven Zwischenprodukten umgewandelt, die ribosomale Proteine, die Erbsubstanz (DNA) und Enzyme des Energiestoffwechsels schädigen. Weil der Wirkstoff rasch über die Niere ausgeschieden wird, entstehen wirksame Konzentrationen nur im Urin; für Nierenbeckenentzündungen oder Infektionen ausserhalb der Harnwege ist er deshalb nicht geeignet.","nebenwirkungen":{"haeufig":["Übelkeit, Appetitlosigkeit, Erbrechen","Kopfschmerzen","Schwindel und Benommenheit"],"gelegentlich":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Durchfall, Bauchschmerzen"],"selten":["Akute Lungenreaktionen (Fieber, Husten, Atemnot, Brustschmerzen)","Chronische Lungenveränderungen bis Lungenfibrose bei Langzeitanwendung","Periphere Polyneuropathie (Kribbeln, Taubheit, Schwäche in Armen und Beinen)","Cholestatische Gelbsucht und Hepatitis (Leberentzündung)","Hämolytische Anämie (Blutzerfall), besonders bei G6PD-Mangel","Blutbildveränderungen (Leukopenie, Agranulozytose, Thrombozytopenie)","Vorübergehender Haarausfall"],"sehrSelten":["Chronisch aktive Hepatitis, Leberversagen","Anaphylaxie (schwere allergische Reaktion) und Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, exfoliative Dermatitis)","Lupus-ähnliches Syndrom","Pankreatitis (Bauchspeicheldrüsenentzündung)","Gutartige Hirndrucksteigerung"],"unbekannt":["Arzneimittelfieber","Antibiotika-assoziierte Durchfälle bis pseudomembranöse Kolitis (Clostridioides difficile)","Aplastische Anämie"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; in den letzten Schwangerschaftswochen und unter der Geburt kontraindiziert, da beim Neugeborenen ein Blutzerfall (hämolytische Anämie) ausgelöst werden kann.","stillzeit":"Geht in geringen Mengen in die Muttermilch über. Nicht anwenden, wenn das gestillte Kind jünger als 1 Monat ist oder einen G6PD-Mangel hat bzw. haben könnte; sonst nach ärztlicher Abwägung.","hinweise":["Mit einer Mahlzeit oder mit Milch einnehmen – das verbessert Verträglichkeit und Aufnahme.","Der Urin kann sich dunkelgelb bis bräunlich verfärben; das ist harmlos.","Bei Husten, Atemnot, Fieber, Gelbsucht oder Kribbeln und Taubheitsgefühl in Händen oder Füssen sofort ärztlich melden.","Bei Langzeitvorbeugung Lungen-, Leber- und Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Retardkapseln"]},"nivolumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, sodass körpereigene Abwehrzellen Krebszellen wieder erkennen und angreifen. Nivolumab ist ein humaner IgG4-Antikörper gegen den Rezeptor PD-1 auf T-Lymphozyten. Er verhindert, dass die vom Tumor gebildeten Liganden PD-L1 und PD-L2 an PD-1 binden und die T-Zellen abschalten. Weil diese Immunbremse auch gesundes Gewebe schützt, können immunvermittelte Entzündungen in praktisch allen Organen auftreten.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit","Hautausschlag, Juckreiz","Durchfall, Übelkeit","Muskel-, Knochen- und Gelenkschmerzen","Appetitlosigkeit","Husten, Atemnot","Erhöhte Leberwerte; Abnahme von Lymphozyten, Neutrophilen und Blutplättchen, Anämie (Laborwerte)"],"haeufig":["Hypothyreose (Schilddrüsenunterfunktion), Hyperthyreose","Pneumonitis (Lungenentzündung durch Immunreaktion)","Kolitis (Dickdarmentzündung), Stomatitis, Erbrechen, Bauchschmerzen, Verstopfung","Infusionsreaktionen, Überempfindlichkeit","Infekte der oberen Atemwege, Lungenentzündung","Kopfschmerzen, Schwindel, periphere Neuropathie","Vitiligo (Weissfleckenkrankheit), trockene Haut, Haarausfall","Fieber, Ödeme, Bluthochdruck, Hyperglykämie"],"gelegentlich":["Nebenniereninsuffizienz, Hypophysitis (Hirnanhangdrüsenentzündung), Thyreoiditis","Diabetes mellitus, diabetische Ketoazidose","Hepatitis","Nephritis (Nierenentzündung), Nierenversagen","Pankreatitis, Gastritis","Uveitis (Augenentzündung)","Herzrhythmusstörungen, Vorhofflimmern","Erythema multiforme, Psoriasis, Nesselsucht"],"selten":["Myokarditis (Herzmuskelentzündung), Perikarderkrankungen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Guillain-Barré-Syndrom, Myasthenie-Syndrom, Enzephalitis","Myositis, Rhabdomyolyse (Muskelzerfall)","Sklerosierende Cholangitis (Gallengangsentzündung)","Sarkoidose"],"unbekannt":["Abstossung transplantierter Organe","Hämophagozytische Lymphohistiozytose (HLH, überschiessende Immunreaktion)","Vogt-Koyanagi-Harada-Syndrom (Entzündung von Augen, Haut und Hirnhäuten)"]},"schwangerschaft":"Nicht empfohlen, ausser der Nutzen überwiegt (der Antikörper gelangt zum Kind). Frauen müssen während und mindestens 5 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Unbekannt, ob Nivolumab in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nach ärztlicher Abwägung entscheiden.","hinweise":["Neue oder stärkere Beschwerden – Durchfall, Bauchschmerzen, Husten, Atemnot, Hautausschlag, Gelbsucht, starke Müdigkeit, Kopfschmerzen, Sehstörungen – sofort melden, auch Wochen bis Monate nach der letzten Gabe.","Die Patientenkarte immer mitführen und bei jedem Arztbesuch zeigen.","Schilddrüsen-, Leber- und Nierenwerte sowie der Blutzucker werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"nivolumab-relatlimab":{"wirkmechanismus":"Löst die Bremsen des Immunsystems, damit körpereigene Abwehrzellen (T-Zellen) Krebszellen besser erkennen und angreifen. Nivolumab blockiert den Rezeptor PD-1, Relatlimab den Rezeptor LAG-3 auf T-Zellen; beide sind hemmende Kontrollpunkte (Checkpoints), die Tumoren nutzen, um der Immunabwehr zu entgehen. Die gleichzeitige Blockade beider Signalwege verstärkt die T-Zell-Aktivierung stärker als die Blockade eines einzelnen. Weil das Immunsystem dabei auch gesunde Organe angreifen kann, entstehen typische immunvermittelte Nebenwirkungen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit","Muskel-, Knochen- und Gelenkschmerzen","Hautausschlag, Juckreiz","Durchfall","Kopfschmerzen","Übelkeit","Hypothyreose (Schilddrüsenunterfunktion)","Erhöhte Leberwerte"],"haeufig":["Hyperthyreose (Schilddrüsenüberfunktion)","Nebenniereninsuffizienz","Hypophysitis (Entzündung der Hirnanhangsdrüse)","Kolitis (Darmentzündung)","Pneumonitis (Entzündung des Lungengewebes)","Hepatitis (Leberentzündung)","Myokarditis (Herzmuskelentzündung)"],"unbekannt":["Nephritis (Nierenentzündung)","Typ-1-Diabetes durch das Immunsystem","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: Die Blockade von PD-1 kann im Tierversuch zum Verlust der Schwangerschaft führen. Frauen im gebärfähigen Alter verhüten während und bis mindestens 5 Monate nach der letzten Dosis.","stillzeit":"Während der Behandlung nicht stillen; ein Risiko für das Kind kann nicht ausgeschlossen werden.","hinweise":["Neue oder zunehmende Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Brustschmerzen oder Hautausschlag sofort melden – auch Wochen bis Monate nach Therapieende.","Patientenkarte stets mitführen und bei jeder ärztlichen Behandlung vorzeigen.","Regelmässige Blutkontrollen (Leber, Niere, Schilddrüse, Blutzucker) während der Behandlung."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"noradrenalin":{"wirkmechanismus":"Hebt den Blutdruck, indem es die Blutgefässe stark verengt. Noradrenalin ist der natürliche Botenstoff des sympathischen Nervensystems; es stimuliert vor allem Alpha-1-Rezeptoren der Gefässmuskulatur und erhöht dadurch den Gefässwiderstand. Über Beta-1-Rezeptoren steigert es zusätzlich mässig die Kontraktionskraft des Herzens, während Beta-2-Rezeptoren kaum angesprochen werden. Durch den Blutdruckanstieg kann der Puls reflektorisch langsamer werden. Die Wirkung setzt sofort ein und klingt nach Ende der Infusion innerhalb weniger Minuten ab.","nebenwirkungen":{"unbekannt":["Angst, Unruhe, Schlaflosigkeit, Verwirrtheit, Schwäche","Kopfschmerzen, Zittern","Herzrasen (Tachykardie), reflektorische Bradykardie, Herzklopfen","Herzrhythmusstörungen bis Kammerflimmern","Myokardischämie (Sauerstoffmangel des Herzmuskels), Stress-Kardiomyopathie","Starker Blutdruckanstieg","Durchblutungsstörung von Fingern, Zehen und Organen bis zum Gewebeuntergang (Nekrose)","Atemnot","Übelkeit, Erbrechen","Harnverhalt","Gewebeschäden bis Nekrose bei Austritt aus der Vene (Paravasat)"]},"schwangerschaft":"Nur bei lebensbedrohlicher Situation nach ärztlicher Abwägung: Noradrenalin kann die Durchblutung der Plazenta vermindern und Wehen auslösen.","stillzeit":"Keine ausreichenden Daten; da Noradrenalin über den Darm kaum aufgenommen wird, ist ein Risiko für den Säugling unwahrscheinlich. Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital als Dauerinfusion, möglichst über einen zentralen Venenkatheter, unter laufender Blutdruck- und EKG-Überwachung gegeben.","Austritt ins Gewebe kann schwere Schäden verursachen – Infusionsstelle regelmässig kontrollieren.","Volumenmangel sollte vorher oder gleichzeitig ausgeglichen werden; die Infusion wird schrittweise reduziert, nicht abrupt beendet."],"darreichung":["Infusionskonzentrat","Injektionslösung"]},"norethisteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon und stabilisiert so die Gebärmutterschleimhaut. Norethisteron bindet an Progesteronrezeptoren und wandelt die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut um; nach Absetzen kommt es zu einer geordneten Abbruchblutung. In höherer Dosis hemmt es die Ausschüttung der Hirnanhangshormone und damit den Eisprung. Es hat zusätzlich eine leichte androgene Wirkung, und ein kleiner Teil wird im Körper zu Ethinylestradiol umgewandelt.","nebenwirkungen":{"sehrHaeufig":["Brustspannen oder Brustschmerzen (bei Hormonersatz mit Estradiol)","Blutungen aus der Scheide, Schmierblutungen (bei Hormonersatz mit Estradiol)"],"haeufig":["Kopfschmerzen","Übelkeit","Gewichtszunahme, Wassereinlagerungen (Ödeme)","Depressive Verstimmung","Scheidenpilz oder Scheidenentzündung","Rückenschmerzen"],"gelegentlich":["Migräne","Libidoveränderungen, Nervosität","Bauchschmerzen, Blähungen","Akne, Haarausfall, vermehrte Behaarung, Juckreiz","Oberflächliche Venenentzündung (Thrombophlebitis)","Überempfindlichkeitsreaktionen"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)"],"unbekannt":["Cholestatische Gelbsucht (Gallenstau)","Chloasma (bräunliche Pigmentflecken)","Nesselsucht, Hautausschlag","Herzinfarkt und Schlaganfall (Klassenrisiko bei Hormonersatz)"]},"schwangerschaft":"Kontraindiziert. Hohe Dosen von Nortestosteron-Gestagenen können bei weiblichen Feten zu einer Vermännlichung der äusseren Geschlechtsorgane führen; vor Behandlungsbeginn eine Schwangerschaft ausschliessen.","stillzeit":"Nicht empfohlen – Norethisteron geht in die Muttermilch über.","hinweise":["Norethisteron als Einzelpräparat ist in der eingesetzten Form kein zuverlässiges Verhütungsmittel; bei Bedarf nichthormonal verhüten.","Bei Zeichen einer Thrombose (geschwollenes, schmerzhaftes Bein, Brustschmerz, plötzliche Atemnot), erstmaliger Migräne oder Sehstörungen sofort absetzen und ärztlichen Rat einholen.","Bei Hormonersatz Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen."],"darreichung":["Tabletten","Filmtabletten (Kombination mit Estradiol)"]},"nortriptylin":{"wirkmechanismus":"Hebt Stimmung und Antrieb, indem es die Konzentration des Botenstoffs Noradrenalin im Gehirn erhöht. Nortriptylin, der wirksame Abbaustoff von Amitriptylin, hemmt vor allem die Wiederaufnahme von Noradrenalin und schwächer die von Serotonin. Es blockiert Muskarin-, Histamin- und Alpha-1-Rezeptoren weniger stark als Amitriptylin und wirkt daher weniger dämpfend und anticholinerg. Der Abbau erfolgt hauptsächlich über CYP2D6; bei langsamen Metabolisierern steigen die Spiegel stark an.","nebenwirkungen":{"haeufig":["Mundtrockenheit","Obstipation (Verstopfung)","Vermehrtes Schwitzen","Zittern (Tremor)","Schwindel, Müdigkeit","Verschwommenes Sehen (Akkommodationsstörungen)","Herzklopfen, Herzrasen","Gewichtszunahme"],"unbekannt":["Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Harnverhalt, Blasenentleerungsstörungen","Verwirrtheit (v. a. bei älteren Menschen), Unruhe, Umschlagen in eine Manie","Krampfanfälle","Herzrhythmus- und Reizleitungsstörungen, QT-Verlängerung","Blutbildveränderungen bis Agranulozytose","Hyponatriämie (Natriummangel)","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungs- und Entzugsstörungen (Atemprobleme, Zittern, Trinkschwäche) möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung, der Säugling ist zu beobachten.","hinweise":["Die stimmungsaufhellende Wirkung setzt erst nach 2–4 Wochen ein.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung.","Vorsicht beim Autofahren, besonders zu Beginn; keinen Alkohol trinken.","EKG und gegebenenfalls Blutspiegel kontrollieren; eine Überdosis ist lebensgefährlich – für Kinder unzugänglich aufbewahren."],"darreichung":["Dragées"]},"nusinersen":{"wirkmechanismus":"Hilft dem Körper, mehr von einem für die Nervenzellen der Muskulatur lebenswichtigen Eiweiss zu bilden. Bei SMA fehlt ein funktionsfähiges SMN1-Gen; das Ersatzgen SMN2 liefert wegen eines Spleissfehlers (Verlust von Exon 7) überwiegend unvollständiges SMN-Protein. Nusinersen ist ein Antisense-Oligonukleotid, das an die SMN2-Prä-mRNA bindet und den Einbau von Exon 7 fördert. So entsteht mehr vollständiges SMN-Protein, das die Motoneuronen im Rückenmark schützt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen nach der Lumbalpunktion","Erbrechen","Rückenschmerzen"],"unbekannt":["Schwere Infektionen wie Meningitis (Hirnhautentzündung)","Aseptische Meningitis","Kommunizierender Hydrozephalus","Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Ausschlag)","Thrombozytopenie und Gerinnungsstörungen","Eiweiss im Urin (Proteinurie)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber in der Schwangerschaft vermeiden.","stillzeit":"Es ist nicht bekannt, ob Nusinersen in die Muttermilch übergeht; über Stillen oder Behandlung wird individuell entschieden.","hinweise":["Die Injektion erfolgt im Spital durch erfahrene Fachpersonen per Lumbalpunktion, nach einer Aufsättigungsphase in regelmässigen Abständen.","Vor jeder Gabe werden Blutplättchen, Gerinnung und Urin kontrolliert.","Nach der Lumbalpunktion können Kopf- und Rückenschmerzen auftreten; bei Fieber, Nackensteifigkeit oder starken Kopfschmerzen sofort ärztlich melden."],"darreichung":["Injektionslösung zur intrathekalen Anwendung (Lumbalpunktion)"]},"nystatin":{"wirkmechanismus":"Tötet Hefepilze ab, indem es ihre Zellhülle durchlöchert. Nystatin bindet an Ergosterol, einen Baustein der Pilzzellmembran, und bildet Poren, durch die lebenswichtige Zellbestandteile austreten; je nach Konzentration wirkt es pilzhemmend oder pilzabtötend, vor allem auf Candida-Arten. Aus dem Magen-Darm-Trakt und über die intakte Haut wird Nystatin praktisch nicht aufgenommen; es wirkt deshalb nur dort, wo es aufgetragen oder geschluckt wird, und eignet sich nicht zur Behandlung von Pilzinfektionen innerer Organe.","nebenwirkungen":{"sehrSelten":["Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Übelkeit, Erbrechen, Durchfall (v. a. bei hohen Dosen)","Reizung der Mundschleimhaut","Überempfindlichkeitsreaktionen wie Hautausschlag oder Nesselsucht","Hautreizung oder Kontaktekzem bei Anwendung auf der Haut"]},"schwangerschaft":"Wird praktisch nicht aufgenommen; die Anwendung ist nach Rücksprache mit Ärztin oder Arzt möglich.","stillzeit":"Wird praktisch nicht aufgenommen; Anwendung in der Stillzeit möglich.","hinweise":["Suspension nach den Mahlzeiten einnehmen und möglichst lange im Mund verteilen, bevor sie geschluckt wird.","Behandlung nach Abklingen der Beschwerden noch etwa 2 Tage fortsetzen, um Rückfälle zu vermeiden.","Bei Säuglingen mit Mundsoor Sauger und Nuggi regelmässig auskochen; bei stillenden Müttern auch die Brustwarzen mitbehandeln lassen."],"darreichung":["Suspension zum Einnehmen","Paste (Kombination mit Zinkoxid)"]}});
